content.text:
{
  "name": "PCO Sensicam CCD科学相机",
  "name_en": "PCO Sensicam CCD scientific camera",
  "manufacturer": "PCO",
  "description": "这是一款用于实验成像采集的 PCO Sensicam CCD 相机。驱动显示其支持曝光控制、触发模式、感兴趣区域（ROI）、像素合并（binning）、成像模式设置，以及 CCD 图像读出，适合实验室中的科学成像与单次/连续采集任务。",
  "description_en": "This is a PCO Sensicam CCD camera for laboratory image acquisition. The driver indicates support for exposure control, trigger mode, region of interest (ROI), pixel binning, imaging mode configuration, and CCD image readout, making it suitable for scientific imaging and single or continuous acquisition tasks in the lab.",
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化相机连接与控制环境。",
      "description_en": "Initialize the camera connection and control environment."
    },
    {
      "action_name": "auto-finalize",
      "description": "关闭相机连接并释放资源。",
      "description_en": "Finalize the camera connection and release resources."
    },
    {
      "action_name": "auto-status",
      "description": "获取相机类型、电子学温度和 CCD 温度状态。",
      "description_en": "Get the camera type, electronics temperature, and CCD temperature status."
    },
    {
      "action_name": "auto-mode",
      "description": "获取或设置成像模式（类型、增益和子模式）。",
      "description_en": "Get or set the imaging mode (type, gain, and submode)."
    },
    {
      "action_name": "auto-trigger",
      "description": "获取或设置触发模式。",
      "description_en": "Get or set the trigger mode."
    },
    {
      "action_name": "auto-roi",
      "description": "获取或设置图像感兴趣区域（ROI）。",
      "description_en": "Get or set the image region of interest (ROI)."
    },
    {
      "action_name": "auto-binning",
      "description": "获取或设置水平和垂直像素合并参数。",
      "description_en": "Get or set the horizontal and vertical pixel binning."
    },
    {
      "action_name": "auto-exposure_time",
      "description": "获取或设置曝光时间。",
      "description_en": "Get or set the exposure time."
    },
    {
      "action_name": "auto-table",
      "description": "获取 COC 参数表。",
      "description_en": "Get the COC parameter table."
    },
    {
      "action_name": "auto-stop_coc",
      "description": "停止相机的 COC 运行。",
      "description_en": "Stop the camera COC operation."
    },
    {
      "action_name": "auto-run_coc",
      "description": "以指定模式启动 COC 运行，例如单次或连续采集。",
      "description_en": "Start COC operation in a specified mode, such as single or continuous acquisition."
    },
    {
      "action_name": "auto-coc",
      "description": "获取或设置命令操作代码（COC）。",
      "description_en": "Get or set the command operation code (COC)."
    },
    {
      "action_name": "auto-image_status",
      "description": "获取图像采集状态。",
      "description_en": "Get the image acquisition status."
    },
    {
      "action_name": "auto-image_size",
      "description": "获取图像尺寸（宽度和高度）。",
      "description_en": "Get the image size (width and height)."
    },
    {
      "action_name": "auto-coc_time",
      "description": "获取 COC 时间参数。",
      "description_en": "Get the COC timing parameter."
    },
    {
      "action_name": "auto-delay_time",
      "description": "获取延迟时间参数。",
      "description_en": "Get the delay time parameter."
    },
    {
      "action_name": "auto-exp_time",
      "description": "获取曝光时间参数。",
      "description_en": "Get the exposure time parameter."
    },
    {
      "action_name": "auto-bel_time",
      "description": "获取 BEL 时间参数。",
      "description_en": "Get the BEL timing parameter."
    },
    {
      "action_name": "auto-expose",
      "description": "执行一次曝光。",
      "description_en": "Perform a single exposure."
    },
    {
      "action_name": "auto-read_out",
      "description": "从 CCD 读出图像数据。",
      "description_en": "Read out image data from the CCD."
    },
    {
      "action_name": "auto-take_image",
      "description": "完成一次曝光并读取图像。",
      "description_en": "Take an image by performing an exposure and reading it out."
    }
  ],
  "tag_hints": [
    "CCD imaging",
    "scientific camera",
    "PCO Sensicam",
    "ROI control",
    "pixel binning",
    "triggered acquisition",
    "exposure control",
    "image readout"
  ]
}

